// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(address actor, uint256 firstTime, uint256 delay) public {
        vm.assume(actor != address(0));
        firstTime = bound(firstTime, 1, 2 ** 60);
        delay = bound(delay, 0, 2 ** 60);

        // first successful call at firstTime
        vm.warp(firstTime);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        c.fallback{value: 10 ether}();

        // second call after `delay` (delay == 0 => equal timestamp)
        vm.warp(firstTime + delay);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        bool ok;
        try c.fallback{value: 10 ether}() { ok = true; } catch { ok = false; }

        // Rule: a successful call must happen at a strictly later timestamp than
        // the one the contract recorded from the previous successful call.
        assertTrue(!ok || firstTime + delay > firstTime);
    }
}

