pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C{value: 10 ether}();
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));
        vm.assume(amount != 10 ether); // inadmissible domain: reference requires exactly 10 ether

        vm.warp(block.timestamp + 1); // ensure block.timestamp > pastBlockTime

        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.fallback{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a fallback call with a value other than exactly 10 ether
        // must always revert. The reference C satisfies this for every input;
        // the mutant (require deleted) accepts such calls and breaks the rule.
        assertTrue(!ok, "call with non-10-ether value must revert");
    }
}

