import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 ts) public {
        ts = bound(ts, 1, type(uint48).max);
        address actor = address(0xABCD);
        vm.deal(actor, 20 ether);
        vm.warp(ts);

        vm.prank(actor);
        c.fallback{value: 10 ether}();

        // Rule: a second call in the SAME block.timestamp must revert because
        // pastBlockTime was set to block.timestamp by the first call.
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: 10 ether}("");
        assertTrue(!ok);
    }
}

