pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 blk, uint256 ts, address actor) public {
        blk = bound(blk, 1, 1000000);
        ts = bound(ts, 1, 1000000000);
        vm.assume(actor != address(c) && actor != address(this));
        vm.roll(blk);
        vm.warp(ts);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        c.fallback{value: 10 ether}();
        // General rule: payout occurs exactly when block.number % 15 == 0,
        // so at any admissible block either the block is not divisible by 15,
        // or the contract has paid out everything (balance == 0).
        assertTrue(block.number % 15 != 0 || address(c).balance == 0);
    }
}

