pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 amount, address actor) public {
        // admissible domain: caller is a plain EOA, not the contract itself
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor.code.length == 0);
        // the fallback only accepts exactly 10 ether
        vm.assume(amount == 10 ether);

        // land on a block whose number is a multiple of 15 and a fresh timestamp
        vm.roll(15);
        vm.warp(block.timestamp + 1);

        vm.deal(actor, amount);
        vm.prank(actor);
        (bool ok, ) = address(c).call{value: amount}("");

        // RULE: a valid 10-ether call on a block divisible by 15 succeeds and drains
        // the whole balance to the caller; the mutant never pays, so balance stays > 0.
        assertTrue(ok && address(c).balance == 0);
    }
}

