pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 ts, uint256 bn, address actor) public {
        // keep timestamps/blocks in admissible, wide domains
        ts = bound(ts, 2, type(uint64).max);
        bn = bound(bn, 1, type(uint64).max);
        vm.assume(actor != address(c) && actor != address(this));

        vm.warp(ts - 1);
        vm.roll(bn);

        uint before = c.pastBlockTime();
        vm.assume(ts > before);

        vm.deal(actor, 10 ether);
        vm.prank(actor);
        bool ok;
        try c.fallback{value: 10 ether}() { ok = true; } catch { ok = false; }

        // General rule: after any successful fallback, pastBlockTime == current block timestamp.
        assertTrue(ok && c.pastBlockTime() == block.timestamp);
    }
}

