pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    ReentrantAttacker attacker;

    function setUp() public { c = new C{value: 10 ether}(); attacker = new ReentrantAttacker(c); }

    function testFuzz_property(uint256 seedTs, uint256 seedBlk) public {
        // admissible domain: a positive timestamp and a block whose number is a multiple of 15 (payout block)
        uint256 ts = bound(seedTs, 1, type(uint64).max);
        uint256 blk = bound(seedBlk, 1, type(uint64).max / 15) * 15;
        vm.warp(ts);
        vm.roll(blk);

        vm.deal(address(attacker), 30 ether);
        vm.prank(address(attacker));
        attacker.enter();

        // General rule: during a payout-triggering call, pastBlockTime is already set to the
        // current timestamp before the payout transfer, so a re-entrant fallback call must fail.
        assertTrue(!attacker.reentered());
    }
}

contract ReentrantAttacker {
    C c;
    bool public reentered;

    constructor(C _c) { c = _c; }

    function enter() external payable {
        (bool ok, ) = address(c).call{value: 10 ether}("");
        ok; // outer call result irrelevant; reentrancy flag is the observable
    }

    receive() external payable {
        // re-enter the fallback with exactly 10 ether; succeeds only if pastBlockTime was NOT yet updated
        (bool ok, ) = address(c).call{value: 10 ether}("");
        if (ok) reentered = true;
    }
}
